import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第三卦 屯 水雷屯 坎上震下","description":"周易 - 第三卦 屯 水雷屯 坎上震下","frontmatter":{"title":"第三卦 屯 水雷屯 坎上震下","description":"周易 - 第三卦 屯 水雷屯 坎上震下"},"headers":[],"relativePath":"classics/zhouyi/004.md","filePath":"classics/zhouyi/004.md"}'),l={name:"classics/zhouyi/004.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="屯" tabindex="-1">屯 <a class="header-anchor" href="#屯" aria-label="Permalink to “屯”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>元，亨，利，貞，勿用，有攸往，利建侯。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>屯，剛柔始交而難生，動乎險中，大亨貞。雷雨之動滿盈，天造草昧，宜建侯而不寧。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>雲，雷，屯；君子以經綸。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>磐桓；利居貞，利建侯。象曰：雖磐桓，志行正也。以貴下賤，大得民也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>屯如(辶顫)如，乘馬班如。匪寇婚媾，女子貞不字，十年乃字。象曰：六二之難，乘 剛也。十年乃字，反常也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>既鹿無虞，惟入於林中，君子幾不如舍，往吝。象曰：既鹿無虞，以縱禽也。君子舍之，往吝窮也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>乘馬班如，求婚媾，無不利。象曰：求而往，明也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>屯其膏，小貞吉，大貞兇。象曰：屯其膏，施未光也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>乘馬班如，泣血漣如。象曰：泣血漣如，何可長也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
